#!/usr/bin/env bash
# Swagger spec drift guard (issue #2082).
#
# apps/server/docs/swagger/{docs.go,swagger.json,swagger.yaml} are generated by
# swag from the handler/DTO annotations, committed, and published: docs.yml
# copies swagger.json/swagger.yaml into the docs site. Nothing verified that the
# committed artifacts still match the source, so an annotation or DTO change
# silently shipped a stale public API spec. That is the recurring failure this
# guard closes: #2057 had to regenerate the spec and found three source changes
# that had gone unregenerated (+220 lines, /api/notifications/resolve-resource,
# extractionJobs, SelfRegistering); #931 was closed with "no CI verifies
# either"; #1128, #1591 and #1684 were the same class.
#
# `task swagger:check` (scripts/check-swagger-annotations.sh) only counts
# handlers that carry an @Router annotation — it cannot see a stale artifact.
# This guard regenerates the spec and fails on any difference, including a
# *new* generated file: `git diff` alone would miss an untracked
# docs_<handler>.go, so detection goes through `git status --porcelain`.
#
# The generator version comes from go.mod, not from a pin here: #2057
# established that the swag CLI must match the compiled github.com/swaggo/swag
# library, so a go.mod bump moves both and there is no second pin to rot.
#
# Cost: ~5 s warm, measured 13.9 s with an empty Go build cache (the generator
# is built once; the server module cache is already warm because the earlier
# `go run` guards in this job compile the module). The ~1m40s worst case needs
# both the module cache and the build cache empty — it was measured once on a
# cold workstation and never happens on the self-hosted runner, whose first run
# of this step took 4.1 s. That is affordable in the
# branch-protection-required `ci` job, which is the only place the guard can
# actually gate: server.yml is path-filtered and advisory, so the same step
# there would surface after merge instead of blocking the PR.
#
# Quiet on success (the generator prints one line per type). Run from anywhere;
# resolves the repo root itself. Wired into CI as its own step in the required
# `ci` job (.github/workflows/ci.yml) and deliberately NOT listed in
# scripts/preflight/all.sh, which that same job also runs — adding it there
# would run the generator twice per PR.
set -euo pipefail

root="$(git rev-parse --show-toplevel)"
cd "$root/apps/server"

swag_version="$(go list -m -f '{{.Version}}' github.com/swaggo/swag)"
if [ -z "$swag_version" ]; then
  echo "swagger drift guard: could not read github.com/swaggo/swag version from apps/server/go.mod" >&2
  exit 1
fi

gen_log="$(mktemp)"
diff_log="$(mktemp)"
trap 'rm -f "$gen_log" "$diff_log"' EXIT

# Build+run the generator once. Its per-type chatter is only useful when the
# generator itself fails, so keep it out of the log until then.
if ! go run "github.com/swaggo/swag/cmd/swag@${swag_version}" \
  init -g cmd/server/main.go -o docs/swagger --parseDependency --parseInternal \
  >"$gen_log" 2>&1; then
  echo "swagger drift guard: swag ${swag_version} failed to generate the spec:" >&2
  cat "$gen_log" >&2
  exit 1
fi

# Untracked + modified + deleted, in one shot. `git diff --exit-code` below
# cannot see a newly emitted docs_<handler>.go because it is untracked.
# `--untracked-files=all` (rather than the default) so a developer whose
# `status.showUntrackedFiles=no` config would otherwise get a silent pass when
# running this by hand.
drift="$(git status --porcelain --untracked-files=all -- docs/swagger)"
tracked_drift=0
git diff --exit-code -- docs/swagger >"$diff_log" 2>&1 || tracked_drift=1

if [ -z "$drift" ] && [ "$tracked_drift" -eq 0 ]; then
  echo "swagger spec up to date (swaggo/swag ${swag_version})"
  exit 0
fi

echo "swagger spec drift: committed apps/server/docs/swagger artifacts do not match the source annotations." >&2
echo "Drifted files (status from git status --porcelain):" >&2
if [ -n "$drift" ]; then
  printf '%s\n' "$drift" >&2
fi

# Bound the diff: docs.go is ~1.4 MB of generated template, so a whole-file
# diff can bury the actionable part.
if [ "$tracked_drift" -ne 0 ]; then
  git diff --stat -- docs/swagger >&2
  echo "--- first 60 diff lines ---" >&2
  head -n 60 "$diff_log" >&2 || true
fi

echo "" >&2
echo "These files are generated from the handler/DTO annotations — never hand-edit them." >&2
echo "Regenerate and commit the result:" >&2
echo "" >&2
echo "    cd apps/server && task swagger" >&2
echo "" >&2
echo "The spec is public API surface: review the regenerated diff before committing." >&2
exit 1
